import { createClient } from "@supabase/supabase-js";

const SUPABASE_URL =
  process.env.REACT_APP_SUPABASE_URL || "https://opxorasggouuzzsvzlvm.supabase.co";
const SUPABASE_PUBLISHABLE_KEY =
  process.env.REACT_APP_SUPABASE_PUBLISHABLE_KEY ||
  "sb_publishable_PjpxLcSpHeOt2MCgl3fUUw_RUFOAb5w";

// Admin sessions intentionally disappear when the browser tab is closed. The
// adapter is defensive for privacy modes where sessionStorage is unavailable.
const sessionStorageAdapter = {
  getItem(key) {
    try { return window.sessionStorage.getItem(key); } catch { return null; }
  },
  setItem(key, value) {
    try { window.sessionStorage.setItem(key, value); } catch { /* no persistence */ }
  },
  removeItem(key) {
    try { window.sessionStorage.removeItem(key); } catch { /* already absent */ }
  },
};

export const adminAuth = createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: sessionStorageAdapter,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    // Implicit links can be opened from an email client into a fresh tab.
    // PKCE would keep its verifier in the originating tab's sessionStorage.
    flowType: "implicit",
  },
});

export async function sendAdminMagicLink(email) {
  const publicPath = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
  const emailRedirectTo = `${window.location.origin}${publicPath}/admin`;
  const { error } = await adminAuth.auth.signInWithOtp({
    email: email.trim(),
    options: { shouldCreateUser: false, emailRedirectTo },
  });
  if (error) throw error;
}

export async function getAdminSession() {
  const { data, error } = await adminAuth.auth.getSession();
  if (error) throw error;
  return data.session;
}

export function onAdminAuthChange(callback) {
  const { data } = adminAuth.auth.onAuthStateChange((_event, session) => callback(session));
  return () => data.subscription.unsubscribe();
}

export async function signOutAdmin() {
  const { error } = await adminAuth.auth.signOut({ scope: "local" });
  if (error) throw error;
}
